import java.sql.Connection;
import java.sql.Statement;
import java.sql.SQLException;

public final class OwnedUnsafe {
    private OwnedUnsafe() {}
    public static int nullLength() {
        String missing = null;
        return missing.length();
    }
    public static boolean lookup(Connection connection, String name) throws SQLException {
        try (Statement statement = connection.createStatement()) {
            return statement.execute("SELECT id FROM accounts WHERE name = '" + name + "'");
        }
    }
}

