import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public final class OwnedSafe {
    private OwnedSafe() {}
    public static int nullLength() {
        String present = "safe";
        return present.length();
    }
    public static boolean lookup(Connection connection, String name) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement("SELECT id FROM accounts WHERE name = ?")) {
            statement.setString(1, name);
            return statement.execute();
        }
    }
}

