import java.lang.reflect.Proxy;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.Statement;

public final class OwnedWitness {
    private OwnedWitness() {}
    static final class Capture implements InvocationHandler {
        String sql = "";
        String parameter = "";
        boolean executed;
        public Object invoke(Object proxy, Method method, Object[] args) {
            String operation = method.getName();
            if (operation.equals("createStatement")) {
                return Proxy.newProxyInstance(OwnedWitness.class.getClassLoader(), new Class<?>[] {Statement.class}, this);
            }
            if (operation.equals("prepareStatement")) {
                sql = (String) args[0];
                return Proxy.newProxyInstance(OwnedWitness.class.getClassLoader(), new Class<?>[] {PreparedStatement.class}, this);
            }
            if (operation.equals("setString")) { parameter = (String) args[1]; return null; }
            if (operation.equals("execute")) {
                if (args != null && args.length > 0) { sql = (String) args[0]; }
                executed = true;
                return false;
            }
            if (operation.equals("close")) { return null; }
            throw new AssertionError("unexpected JDBC call: " + operation);
        }
        Connection connection() {
            return (Connection) Proxy.newProxyInstance(OwnedWitness.class.getClassLoader(), new Class<?>[] {Connection.class}, this);
        }
    }
    public static void main(String[] args) throws Exception {
        boolean unsafeNull = false;
        try { OwnedUnsafe.nullLength(); } catch (NullPointerException expected) { unsafeNull = true; }
        int safeLength = OwnedSafe.nullLength();
        String input = "Rivera";
        Capture unsafe = new Capture();
        Capture safe = new Capture();
        OwnedUnsafe.lookup(unsafe.connection(), input);
        OwnedSafe.lookup(safe.connection(), input);
        boolean interpolated = unsafe.executed && unsafe.sql.contains(input);
        boolean parameterized = safe.executed && safe.sql.equals("SELECT id FROM accounts WHERE name = ?");
        boolean parameterBound = safe.parameter.equals(input);
        if (!unsafeNull || safeLength != 4 || !interpolated || !parameterized || !parameterBound) {
            throw new AssertionError("owned positive or corrected control disagrees");
        }
        System.out.println("{\"unsafe_null_throws\":true,\"safe_length\":4,\"unsafe_sql_inlines_input\":true,\"safe_sql_uses_placeholder\":true,\"safe_bound_parameter_matches\":true,\"database_connections_opened\":0}");
    }
}
